#!/usr/bin/env node
// Fixture assertion for the browser benchmark: uploads the two deterministic
// fixtures (generated by tools/test-fixtures.mjs) in REAL Chromium and asserts
// the numbers layerscope is expected to report, plus that three consecutive
// uploads of the same fixture in the same page give identical results.
//
// Also asserts the idle landing page (desktop 1440x900 and mobile 390x844):
// the #sample-btn button is visible and enabled on load, and no "Reading
// archive" loading text is visible while the page is idle.
//
// Fixture content: base layer with 200 KiB random app/config.txt + small
// files; layer 2 adds a 5 MiB random data/big.bin; layer 3 is the whiteout
// data/.wh.big.bin; layer 4 rewrites app/config.txt with 200 KiB random;
// one empty_layer CMD history entry. test1 is the legacy docker-save layout,
// test3 the identical content as an OCI layout with zstd layers.
//
// Expected (verified against the analysis engine on node v22.22.3):
//   4 layers — wasted 5,652,480 bytes ("5.39 MB") — efficiency 3.6248% ("3.6%") — reclaimable 5,447,680 bytes ("5.20 MB").
//
// Usage:
//   node tools/browser-fixtures.mjs --url http://127.0.0.1:8321 --test1 /path/test1-waste.tar --test3 /path/test3-zstd.tar
// Exits non-zero if any assertion or console/page error occurs.

import { chromium } from 'playwright-core';
import { existsSync } from 'node:fs';
import { LONG_TAG } from './test-fixtures.mjs';

const args = process.argv.slice(2);
const getArg = (flag) => { const i = args.indexOf(flag); return i >= 0 ? args[i + 1] : null; };
const url = getArg('--url') || 'http://127.0.0.1:8321';
const test1 = getArg('--test1');
const test3 = getArg('--test3');
const longname = getArg('--longname'); // optional: test4-longname.tar (header-card long-name check)
if (!test1 || !test3) { console.error('usage: node tools/browser-fixtures.mjs --url URL --test1 tar --test3 tar [--longname tar]'); process.exit(2); }
for (const [label, img] of [['test1-waste.tar', test1], ['test3-zstd.tar', test3]]) {
  if (!existsSync(img)) { console.error(`${label} not found: ${img}`); process.exit(2); }
}
if (longname && !existsSync(longname)) { console.error(`test4-longname.tar not found: ${longname}`); process.exit(2); }

const EXPECTED = {
  layers: '4 layers',
  wasted: '5.39 MB',       // 5,652,480 bytes
  reclaimable: '5.20 MB',  // 5,447,680 bytes
  efficiency: '3.6%',      // 3.6248% (UI renders one decimal)
};

const browser = await chromium.launch();
let failures = 0;
let anyConsoleErrors = false;
const fail = (fixture, msg) => { failures++; console.error(`::error::browser-fixtures ${fixture}: ${msg}`); };

// ---------- idle landing page: sample button + no loading text ----------
// The "Try a sample image" button must be visible and enabled on load, and
// the idle page must not show any "Reading archive" loading text — checked
// on a desktop viewport and on a 390x844 mobile viewport.
for (const [label, viewport] of [
  ['desktop 1440x900', { width: 1440, height: 900 }],
  ['mobile 390x844', { width: 390, height: 844 }],
]) {
  const page = await browser.newPage({ viewport });
  const consoleErrors = [];
  page.on('pageerror', (e) => consoleErrors.push(`pageerror: ${e.message}`));
  page.on('console', (m) => { if (m.type() === 'error') consoleErrors.push(`console: ${m.text()}`); });

  await page.goto(url, { waitUntil: 'load', timeout: 60000 });

  const sampleBtn = page.locator('#sample-btn');
  const btnVisible = await sampleBtn.isVisible();
  const btnEnabled = await sampleBtn.isEnabled();
  console.log(`::notice::browser-fixtures idle ${label}: #sample-btn visible=${btnVisible} enabled=${btnEnabled}`);
  if (!btnVisible) fail('idle', `${label}: #sample-btn is not visible on load`);
  if (!btnEnabled) fail('idle', `${label}: #sample-btn is not enabled on load`);

  // Elements that directly hold a "Reading archive" text node, with a real
  // rendered box — an ancestor with display:none empties the box, so the
  // hidden #progress-overlay copy of the string does not count as visible.
  const visibleLoading = await page.evaluate(() => {
    const hits = new Set();
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    let node;
    while ((node = walker.nextNode())) {
      if (!/reading archive/i.test(node.nodeValue || '')) continue;
      const el = node.parentElement;
      if (!el) continue;
      const cs = window.getComputedStyle(el);
      if (cs.display === 'none' || cs.visibility === 'hidden' || cs.visibility === 'collapse') continue;
      if (parseFloat(cs.opacity || '1') === 0) continue;
      const rect = el.getBoundingClientRect();
      if (rect.width === 0 || rect.height === 0) continue;
      if (cs.position !== 'fixed' && !el.offsetParent) continue;
      hits.add(`${el.tagName.toLowerCase()}#${el.id || ''}`);
    }
    return [...hits];
  });
  if (visibleLoading.length) {
    fail('idle', `${label}: "Reading archive" loading text is visible while the page is idle (in: ${visibleLoading.join(', ')})`);
  }
  if (await page.locator('#progress-overlay').isVisible()) {
    fail('idle', `${label}: #progress-overlay is visible on the idle page`);
  }
  if (consoleErrors.length) {
    anyConsoleErrors = true;
    fail('idle', `${label}: console/page errors: ${consoleErrors.join(' | ')}`);
  }
  await page.close();
}

for (const [name, img] of [['test1-waste.tar', test1], ['test3-zstd.tar', test3]]) {
  const page = await browser.newPage();
  const consoleErrors = [];
  page.on('pageerror', (e) => consoleErrors.push(`pageerror: ${e.message}`));
  page.on('console', (m) => { if (m.type() === 'error') consoleErrors.push(`console: ${m.text()}`); });

  await page.goto(url, { waitUntil: 'load', timeout: 60000 });

  const waitForAnalysis = async () => {
    const outcome = await Promise.race([
      page.waitForFunction(() => {
        const a = document.getElementById('analysis');
        const o = document.getElementById('progress-overlay');
        return a && !a.hidden && o && o.hidden;
      }, null, { timeout: 600000, polling: 100 }).then(() => 'ok'),
      page.waitForSelector('#error-box', { state: 'visible', timeout: 600000 }).then(() => 'error'),
    ]);
    if (outcome === 'error') {
      const text = await page.$eval('#error-box', (el) => el.textContent.trim());
      throw new Error(`analysis failed in the browser for ${img}: ${text}`);
    }
  };

  const dumpStats = () => page.evaluate(() => ({
    chipLayers: document.getElementById('chip-layers')?.textContent ?? null,
    statWasted: document.getElementById('stat-wasted')?.textContent ?? null,
    wsWasted: document.getElementById('ws-wasted')?.textContent ?? null,
    statReclaimable: document.getElementById('stat-reclaimable')?.textContent ?? null,
    wsReclaimable: document.getElementById('ws-reclaimable')?.textContent ?? null,
    gaugeValue: document.getElementById('gauge-value')?.textContent ?? null,
    wsEfficiency: document.getElementById('ws-efficiency')?.textContent ?? null,
  }));

  const dumps = [];
  for (let run = 1; run <= 3; run++) {
    if (run > 1) {
      await page.click('#analyze-another');
      await page.waitForFunction(() => !document.getElementById('landing').hidden, null, { timeout: 30000, polling: 100 });
    }
    await page.setInputFiles('#file-input', img);
    await waitForAnalysis();
    const dump = await dumpStats();
    dumps.push(dump);
    console.log(`::notice::browser-fixtures ${name} run${run}: ${JSON.stringify(dump)}`);

    if (dump.chipLayers !== EXPECTED.layers) fail(name, `layers ${JSON.stringify(dump.chipLayers)} (run ${run}), expected ${EXPECTED.layers}`);
    if (dump.statWasted !== EXPECTED.wasted) fail(name, `stat-wasted ${JSON.stringify(dump.statWasted)} (run ${run}), expected ${EXPECTED.wasted}`);
    if (dump.wsWasted !== EXPECTED.wasted) fail(name, `ws-wasted ${JSON.stringify(dump.wsWasted)} (run ${run}), expected ${EXPECTED.wasted}`);
    if (dump.statReclaimable !== EXPECTED.reclaimable) fail(name, `stat-reclaimable ${JSON.stringify(dump.statReclaimable)} (run ${run}), expected ${EXPECTED.reclaimable}`);
    if (dump.wsReclaimable !== EXPECTED.reclaimable) fail(name, `ws-reclaimable ${JSON.stringify(dump.wsReclaimable)} (run ${run}), expected ${EXPECTED.reclaimable}`);
    if (dump.gaugeValue !== EXPECTED.efficiency) fail(name, `gauge ${JSON.stringify(dump.gaugeValue)} (run ${run}), expected ${EXPECTED.efficiency}`);
    if (dump.wsEfficiency !== EXPECTED.efficiency) fail(name, `ws-efficiency ${JSON.stringify(dump.wsEfficiency)} (run ${run}), expected ${EXPECTED.efficiency}`);
  }

  // deterministic across uploads in the same page
  for (let run = 2; run <= 3; run++) {
    if (JSON.stringify(dumps[run - 1]) !== JSON.stringify(dumps[0])) {
      fail(name, `run ${run} stats differ from run 1: ${JSON.stringify(dumps[run - 1])} vs ${JSON.stringify(dumps[0])}`);
    }
  }
  if (consoleErrors.length) {
    anyConsoleErrors = true;
    fail(name, `console/page errors: ${consoleErrors.join(' | ')}`);
  }
  await page.close();
}

// ---------- long repo tag must not leak into the "Total size" column ----------
// Uploads the long-name fixture, then checks the #image-name header element:
//   1. textContent is exactly the tag (analyzer renders RepoTags[0] as-is)
//   2. title attribute carries the full string (hover discovery)
//   3. its right edge never reaches the .summary-stats left edge
//   4. it is one ellipsized line (white-space: nowrap; overflow: hidden; text-overflow: ellipsis)
if (longname) {
  const longBrowser = await chromium.launch();
  const page = await longBrowser.newPage();
  const consoleErrors = [];
  page.on('pageerror', (e) => consoleErrors.push(`pageerror: ${e.message}`));
  page.on('console', (m) => { if (m.type() === 'error') consoleErrors.push(`console: ${m.text()}`); });

  await page.goto(url, { waitUntil: 'load', timeout: 60000 });
  await page.setInputFiles('#file-input', longname);
  const outcome = await Promise.race([
    page.waitForFunction(() => {
      const a = document.getElementById('analysis');
      const o = document.getElementById('progress-overlay');
      return a && !a.hidden && o && o.hidden;
    }, null, { timeout: 300000, polling: 100 }).then(() => 'ok'),
    page.waitForSelector('#error-box', { state: 'visible', timeout: 300000 }).then(() => 'error'),
  ]);
  if (outcome === 'error') {
    const msg = await page.$eval('#error-box', (el) => el.textContent.trim());
    fail('test4-longname.tar', `analysis failed in the browser for longname fixture: ${msg}`);
  } else {
    const r = await page.evaluate(() => {
      const el = document.getElementById('image-name');
      const stats = document.querySelector('.summary-stats');
      const cs = getComputedStyle(el);
      const elRect = el.getBoundingClientRect();
      const statsRect = stats.getBoundingClientRect();
      return {
        text: el.textContent,
        title: el.getAttribute('title'),
        right: elRect.right,
        statsLeft: statsRect.left,
        whiteSpace: cs.whiteSpace,
        overflow: cs.overflow,
        textOverflow: cs.textOverflow,
        innerWidth: window.innerWidth,
      };
    });
    console.log(`::notice::browser-fixtures test4-longname.tar: ${JSON.stringify(r)}`);
    if (r.text !== LONG_TAG) fail('test4-longname.tar', `#image-name text ${JSON.stringify(r.text)}, expected the full tag`);
    if (r.title !== LONG_TAG) fail('test4-longname.tar', `title attribute ${JSON.stringify(r.title)}, expected the full tag`);
    if (!(r.right <= r.statsLeft + 1)) fail('test4-longname.tar', `header overlaps .summary-stats: image-name right ${r.right} > stats left ${r.statsLeft}`);
    if (r.whiteSpace !== 'nowrap') fail('test4-longname.tar', `white-space ${JSON.stringify(r.whiteSpace)}, expected nowrap (ellipsized single line)`);
    if (r.overflow !== 'hidden') fail('test4-longname.tar', `overflow ${JSON.stringify(r.overflow)}, expected hidden`);
    if (r.textOverflow !== 'ellipsis') fail('test4-longname.tar', `text-overflow ${JSON.stringify(r.textOverflow)}, expected ellipsis`);
    if (consoleErrors.length) fail('test4-longname.tar', `console/page errors: ${consoleErrors.join(' | ')}`);
  }
  await longBrowser.close();
}

await browser.close();
if (failures > 0 || anyConsoleErrors) {
  console.error(`browser-fixtures FAILED with ${failures} failure(s)`);
  process.exit(1);
}
console.log('::notice::browser-fixtures PASS — idle landing checks (desktop + 390x844) green; wasted-waste fixtures report identical numbers on all 3 uploads (longname header check ran when --longname was passed)');
